CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity. 320 chars is the RFC 5321 maximum for an address.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Name shown on shared files and comments.
	"display_name" VARCHAR(120) NOT NULL,
	-- Argon2id hash. Null for accounts that only ever sign in through SSO.
	"password_hash" VARCHAR(255),
	-- The account root. Null only for the instant between inserting the user and creating their root folder.
	"root_folder_id" BIGINT,
	-- Plan allowance. Compared against storage_usage.logical_bytes, not against physical storage.
	"quota_bytes" BIGINT NOT NULL DEFAULT 2147483648,
	-- Blocks uploads and link resolution without deleting any data.
	"is_suspended" BOOLEAN NOT NULL DEFAULT false,
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'An account. Everything a user stores hangs off their root folder, so there is no separate concept of a drive or a workspace at this layer.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Login identity. 320 chars is the RFC 5321 maximum for an address.';
COMMENT ON COLUMN "users"."display_name" IS 'Name shown on shared files and comments.';
COMMENT ON COLUMN "users"."password_hash" IS 'Argon2id hash. Null for accounts that only ever sign in through SSO.';
COMMENT ON COLUMN "users"."root_folder_id" IS 'The account root. Null only for the instant between inserting the user and creating their root folder.';
COMMENT ON COLUMN "users"."quota_bytes" IS 'Plan allowance. Compared against storage_usage.logical_bytes, not against physical storage.';
COMMENT ON COLUMN "users"."is_suspended" IS 'Blocks uploads and link resolution without deleting any data.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';

CREATE INDEX "idx_users_created_at"
ON "users" ("created_at");

CREATE TABLE IF NOT EXISTS "folders" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account whose quota this subtree counts against, even when other people can write to it.
	"owner_id" BIGINT NOT NULL,
	-- Containing folder. Null exactly once per account, for the root.
	"parent_id" BIGINT,
	-- Single path segment. The full path is never stored - it is reconstructed by walking parents, so a rename is one UPDATE instead of a subtree rewrite.
	"name" VARCHAR(255) NOT NULL,
	-- Cached distance from the root. Lets a listing query cap recursion depth without a CTE.
	"path_depth" INTEGER NOT NULL DEFAULT 0,
	-- Soft-delete marker. Set when the folder goes to trash; children keep their own null value so restoring the parent restores the shape.
	"deleted_at" TIMESTAMPTZ,
	-- Row creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Last rename or move.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "folders" IS 'Self-referencing folder tree (adjacency list). Names are unique only among siblings, which is exactly the rule a filesystem enforces and the reason the unique index is composite.';
COMMENT ON COLUMN "folders"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "folders"."owner_id" IS 'Account whose quota this subtree counts against, even when other people can write to it.';
COMMENT ON COLUMN "folders"."parent_id" IS 'Containing folder. Null exactly once per account, for the root.';
COMMENT ON COLUMN "folders"."name" IS 'Single path segment. The full path is never stored - it is reconstructed by walking parents, so a rename is one UPDATE instead of a subtree rewrite.';
COMMENT ON COLUMN "folders"."path_depth" IS 'Cached distance from the root. Lets a listing query cap recursion depth without a CTE.';
COMMENT ON COLUMN "folders"."deleted_at" IS 'Soft-delete marker. Set when the folder goes to trash; children keep their own null value so restoring the parent restores the shape.';
COMMENT ON COLUMN "folders"."created_at" IS 'Row creation time.';
COMMENT ON COLUMN "folders"."updated_at" IS 'Last rename or move.';

CREATE UNIQUE INDEX "uq_folders_parent_name"
ON "folders" ("parent_id", "name");
CREATE INDEX "idx_folders_owner_deleted"
ON "folders" ("owner_id", "deleted_at");

CREATE TABLE IF NOT EXISTS "files" (
	-- Surrogate primary key. Stable across renames, moves and every new version.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account charged for the file. Does not change when the file is shared.
	"owner_id" BIGINT NOT NULL,
	-- Containing folder. Moving a file is an update to this column and nothing else.
	"folder_id" BIGINT NOT NULL,
	-- The version served on download. Null between creating the file row and uploading its first version.
	"current_version_id" BIGINT,
	-- Filename including extension. One path segment, like folders.name.
	"name" VARCHAR(255) NOT NULL,
	-- MIME type sniffed at upload, used to pick a preview renderer.
	"content_type" VARCHAR(150) NOT NULL DEFAULT 'application/octet-stream',
	-- Set while a desktop client holds an exclusive edit lock, so a second client uploads a conflicted copy instead of overwriting.
	"is_locked" BOOLEAN NOT NULL DEFAULT false,
	-- Soft-delete marker; the matching trash_items row carries the retention deadline.
	"deleted_at" TIMESTAMPTZ,
	-- First upload time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Time of the newest version or metadata change. Drives the "recent" list.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "files" IS 'The identity of a document, separate from its bytes. Every mutable fact a user sees - name, location, sharing - lives here; the content lives in immutable versions.';
COMMENT ON COLUMN "files"."id" IS 'Surrogate primary key. Stable across renames, moves and every new version.';
COMMENT ON COLUMN "files"."owner_id" IS 'Account charged for the file. Does not change when the file is shared.';
COMMENT ON COLUMN "files"."folder_id" IS 'Containing folder. Moving a file is an update to this column and nothing else.';
COMMENT ON COLUMN "files"."current_version_id" IS 'The version served on download. Null between creating the file row and uploading its first version.';
COMMENT ON COLUMN "files"."name" IS 'Filename including extension. One path segment, like folders.name.';
COMMENT ON COLUMN "files"."content_type" IS 'MIME type sniffed at upload, used to pick a preview renderer.';
COMMENT ON COLUMN "files"."is_locked" IS 'Set while a desktop client holds an exclusive edit lock, so a second client uploads a conflicted copy instead of overwriting.';
COMMENT ON COLUMN "files"."deleted_at" IS 'Soft-delete marker; the matching trash_items row carries the retention deadline.';
COMMENT ON COLUMN "files"."created_at" IS 'First upload time.';
COMMENT ON COLUMN "files"."updated_at" IS 'Time of the newest version or metadata change. Drives the "recent" list.';

CREATE UNIQUE INDEX "uq_files_folder_name"
ON "files" ("folder_id", "name");
CREATE INDEX "idx_files_owner_updated"
ON "files" ("owner_id", "updated_at");

CREATE TABLE IF NOT EXISTS "file_versions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- File this revision belongs to.
	"file_id" BIGINT NOT NULL,
	-- Monotonic counter per file, starting at 1. Human-facing; never reused after a version is pruned.
	"version_number" INTEGER NOT NULL,
	-- Who uploaded it. Null when the uploader account has been deleted but the revision must survive for collaborators.
	"author_id" BIGINT,
	-- Logical size of the assembled file. Sum of the referenced block sizes.
	"size_bytes" BIGINT NOT NULL,
	-- SHA-256 of the whole file. Lets a client skip an upload entirely when the server already has this exact content.
	"content_hash" CHAR(64) NOT NULL,
	-- Device that produced the revision, for the activity feed. Null for web uploads.
	"device_id" BIGINT,
	-- Upload completion time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "file_versions" IS 'An immutable snapshot of file content. Versions are append-only, which is what makes history, restore and conflict resolution reads rather than reconstructions.';
COMMENT ON COLUMN "file_versions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "file_versions"."file_id" IS 'File this revision belongs to.';
COMMENT ON COLUMN "file_versions"."version_number" IS 'Monotonic counter per file, starting at 1. Human-facing; never reused after a version is pruned.';
COMMENT ON COLUMN "file_versions"."author_id" IS 'Who uploaded it. Null when the uploader account has been deleted but the revision must survive for collaborators.';
COMMENT ON COLUMN "file_versions"."size_bytes" IS 'Logical size of the assembled file. Sum of the referenced block sizes.';
COMMENT ON COLUMN "file_versions"."content_hash" IS 'SHA-256 of the whole file. Lets a client skip an upload entirely when the server already has this exact content.';
COMMENT ON COLUMN "file_versions"."device_id" IS 'Device that produced the revision, for the activity feed. Null for web uploads.';
COMMENT ON COLUMN "file_versions"."created_at" IS 'Upload completion time.';

CREATE UNIQUE INDEX "uq_file_versions_file_number"
ON "file_versions" ("file_id", "version_number");
CREATE INDEX "idx_file_versions_content_hash"
ON "file_versions" ("content_hash");

CREATE TABLE IF NOT EXISTS "blocks" (
	-- Surrogate primary key. Internal only - callers address a block by its hash.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- SHA-256 of the block bytes. This unique constraint is the entire deduplication mechanism: a second upload of identical content finds this row and stores nothing.
	"hash" CHAR(64) NOT NULL UNIQUE,
	-- Byte length of this chunk, typically up to 4 MiB. Needed to compute offsets when reassembling a file.
	"size_bytes" INTEGER NOT NULL,
	-- Object key in the blob store. Kept separate from the hash so blocks can be migrated between buckets or tiers.
	"storage_key" VARCHAR(255) NOT NULL,
	-- Number of file_version_blocks rows pointing here. A block is only eligible for deletion at zero, and only after a grace period.
	"ref_count" INTEGER NOT NULL DEFAULT 0,
	-- hot | cold | archive. Blocks referenced only by old versions get demoted.
	"storage_class" VARCHAR(20) NOT NULL DEFAULT 'hot',
	-- When these bytes were first seen anywhere in the system.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "blocks" IS 'Content-addressed chunk store, global across all users. The same bytes uploaded by a thousand accounts are one row and one object; this table is why logical and physical storage differ by an order of magnitude.';
COMMENT ON COLUMN "blocks"."id" IS 'Surrogate primary key. Internal only - callers address a block by its hash.';
COMMENT ON COLUMN "blocks"."hash" IS 'SHA-256 of the block bytes. This unique constraint is the entire deduplication mechanism: a second upload of identical content finds this row and stores nothing.';
COMMENT ON COLUMN "blocks"."size_bytes" IS 'Byte length of this chunk, typically up to 4 MiB. Needed to compute offsets when reassembling a file.';
COMMENT ON COLUMN "blocks"."storage_key" IS 'Object key in the blob store. Kept separate from the hash so blocks can be migrated between buckets or tiers.';
COMMENT ON COLUMN "blocks"."ref_count" IS 'Number of file_version_blocks rows pointing here. A block is only eligible for deletion at zero, and only after a grace period.';
COMMENT ON COLUMN "blocks"."storage_class" IS 'hot | cold | archive. Blocks referenced only by old versions get demoted.';
COMMENT ON COLUMN "blocks"."created_at" IS 'When these bytes were first seen anywhere in the system.';

CREATE INDEX "idx_blocks_refcount_class"
ON "blocks" ("ref_count", "storage_class");

CREATE TABLE IF NOT EXISTS "file_version_blocks" (
	-- Version being assembled. Part of the composite key.
	"version_id" BIGINT,
	-- Zero-based position of this block in the file. Part of the composite key, and the sort order for reassembly.
	"block_index" INTEGER,
	-- Chunk stored at this position. Many versions across many accounts point at the same block row.
	"block_id" BIGINT NOT NULL,
	PRIMARY KEY("version_id", "block_index")
);

COMMENT ON TABLE "file_version_blocks" IS 'The manifest that turns a pile of shared chunks back into a specific file. A version is nothing but an ordered list of block ids, so an edit to the end of a large file uploads one new block and reuses the rest.';
COMMENT ON COLUMN "file_version_blocks"."version_id" IS 'Version being assembled. Part of the composite key.';
COMMENT ON COLUMN "file_version_blocks"."block_index" IS 'Zero-based position of this block in the file. Part of the composite key, and the sort order for reassembly.';
COMMENT ON COLUMN "file_version_blocks"."block_id" IS 'Chunk stored at this position. Many versions across many accounts point at the same block row.';

CREATE INDEX "idx_fvb_block"
ON "file_version_blocks" ("block_id");

CREATE TABLE IF NOT EXISTS "shares" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Shared file. Exactly one of file_id and folder_id is set.
	"file_id" BIGINT,
	-- Shared folder. Grants apply to the whole subtree below it.
	"folder_id" BIGINT,
	-- User receiving access.
	"grantee_id" BIGINT NOT NULL,
	-- User who created the share. Null once that account is deleted, so the grant survives an offboarding.
	"granted_by_id" BIGINT,
	-- view | comment | edit | owner. Checked against the nearest ancestor share, not just the exact node.
	"permission" VARCHAR(16) NOT NULL DEFAULT 'view',
	-- When the grantee added the share to their own tree. Null while it is still a pending invitation.
	"accepted_at" TIMESTAMPTZ,
	-- Grant time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "shares" IS 'Direct grants to named accounts. Permission resolution walks up the folder tree and takes the most permissive matching grant, which is why a share on a folder needs no rows for the files inside it.';
COMMENT ON COLUMN "shares"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "shares"."file_id" IS 'Shared file. Exactly one of file_id and folder_id is set.';
COMMENT ON COLUMN "shares"."folder_id" IS 'Shared folder. Grants apply to the whole subtree below it.';
COMMENT ON COLUMN "shares"."grantee_id" IS 'User receiving access.';
COMMENT ON COLUMN "shares"."granted_by_id" IS 'User who created the share. Null once that account is deleted, so the grant survives an offboarding.';
COMMENT ON COLUMN "shares"."permission" IS 'view | comment | edit | owner. Checked against the nearest ancestor share, not just the exact node.';
COMMENT ON COLUMN "shares"."accepted_at" IS 'When the grantee added the share to their own tree. Null while it is still a pending invitation.';
COMMENT ON COLUMN "shares"."created_at" IS 'Grant time.';

CREATE INDEX "idx_shares_grantee_accepted"
ON "shares" ("grantee_id", "accepted_at");
CREATE UNIQUE INDEX "uq_shares_folder_grantee"
ON "shares" ("folder_id", "grantee_id");

CREATE TABLE IF NOT EXISTS "public_links" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Random URL segment, at least 128 bits of entropy. The link is the credential, so it is generated by a CSPRNG and never derived from the file id.
	"token" VARCHAR(64) NOT NULL UNIQUE,
	-- Linked file. Exactly one of file_id and folder_id is set.
	"file_id" BIGINT,
	-- Linked folder, served as a browsable listing.
	"folder_id" BIGINT,
	-- Owner of the link, for auditing and revocation.
	"created_by_id" BIGINT NOT NULL,
	-- Optional passphrase gate. Null means the link alone is sufficient.
	"password_hash" VARCHAR(255),
	-- Turns a folder link into a drop box that anonymous visitors can write to.
	"allow_upload" BOOLEAN NOT NULL DEFAULT false,
	-- Hard expiry. Null means the link lives until it is revoked.
	"expires_at" TIMESTAMPTZ,
	-- Optional cap; the link stops resolving once download_count reaches it.
	"max_downloads" INTEGER,
	-- Incremented on each successful fetch. Kept here rather than counted from a log so the cap can be enforced in one statement.
	"download_count" INTEGER NOT NULL DEFAULT 0,
	-- Manual kill switch. Set instead of deleting the row so an audit can still explain a past download.
	"revoked_at" TIMESTAMPTZ,
	-- Link creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "public_links" IS 'Anonymous access by URL. Expiry, download caps and revocation all live here rather than on the file, because the same file can be exposed by several links with different rules.';
COMMENT ON COLUMN "public_links"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "public_links"."token" IS 'Random URL segment, at least 128 bits of entropy. The link is the credential, so it is generated by a CSPRNG and never derived from the file id.';
COMMENT ON COLUMN "public_links"."file_id" IS 'Linked file. Exactly one of file_id and folder_id is set.';
COMMENT ON COLUMN "public_links"."folder_id" IS 'Linked folder, served as a browsable listing.';
COMMENT ON COLUMN "public_links"."created_by_id" IS 'Owner of the link, for auditing and revocation.';
COMMENT ON COLUMN "public_links"."password_hash" IS 'Optional passphrase gate. Null means the link alone is sufficient.';
COMMENT ON COLUMN "public_links"."allow_upload" IS 'Turns a folder link into a drop box that anonymous visitors can write to.';
COMMENT ON COLUMN "public_links"."expires_at" IS 'Hard expiry. Null means the link lives until it is revoked.';
COMMENT ON COLUMN "public_links"."max_downloads" IS 'Optional cap; the link stops resolving once download_count reaches it.';
COMMENT ON COLUMN "public_links"."download_count" IS 'Incremented on each successful fetch. Kept here rather than counted from a log so the cap can be enforced in one statement.';
COMMENT ON COLUMN "public_links"."revoked_at" IS 'Manual kill switch. Set instead of deleting the row so an audit can still explain a past download.';
COMMENT ON COLUMN "public_links"."created_at" IS 'Link creation time.';

CREATE INDEX "idx_public_links_creator_revoked"
ON "public_links" ("created_by_id", "revoked_at");

CREATE TABLE IF NOT EXISTS "devices" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owner of the device.
	"user_id" BIGINT NOT NULL,
	-- User-visible label, e.g. "Work MacBook".
	"name" VARCHAR(120) NOT NULL,
	-- macos | windows | linux | ios | android | web.
	"platform" VARCHAR(20) NOT NULL,
	-- Highest sync_events.id this device has applied. The whole sync protocol is "give me everything after this number", which makes reconnecting cheap and idempotent.
	"sync_cursor" BIGINT NOT NULL DEFAULT 0,
	-- Last contact. Drives the "this device has not synced in a while" warning.
	"last_seen_at" TIMESTAMPTZ,
	-- Set when the user unlinks the device remotely; its tokens stop working and the local cache is wiped on next contact.
	"revoked_at" TIMESTAMPTZ,
	-- Link time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "devices" IS 'A linked client. The per-device cursor is the reason two machines can be arbitrarily far apart in sync progress without the server tracking a diff per pair.';
COMMENT ON COLUMN "devices"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "devices"."user_id" IS 'Owner of the device.';
COMMENT ON COLUMN "devices"."name" IS 'User-visible label, e.g. "Work MacBook".';
COMMENT ON COLUMN "devices"."platform" IS 'macos | windows | linux | ios | android | web.';
COMMENT ON COLUMN "devices"."sync_cursor" IS 'Highest sync_events.id this device has applied. The whole sync protocol is "give me everything after this number", which makes reconnecting cheap and idempotent.';
COMMENT ON COLUMN "devices"."last_seen_at" IS 'Last contact. Drives the "this device has not synced in a while" warning.';
COMMENT ON COLUMN "devices"."revoked_at" IS 'Set when the user unlinks the device remotely; its tokens stop working and the local cache is wiped on next contact.';
COMMENT ON COLUMN "devices"."created_at" IS 'Link time.';

CREATE INDEX "idx_devices_user_revoked"
ON "devices" ("user_id", "revoked_at");

CREATE TABLE IF NOT EXISTS "sync_events" (
	-- Monotonic sequence. Ordering is the point: it is the cursor every device reads against.
	"id" BIGSERIAL,
	-- Account whose stream this event belongs to. Shared content is fanned out into each participant stream.
	"user_id" BIGINT NOT NULL,
	-- Affected file. Null for folder-only events.
	"file_id" BIGINT,
	-- Affected folder. Null for file-only events.
	"folder_id" BIGINT,
	-- created | updated | moved | deleted | restored | permission_changed.
	"action" VARCHAR(20) NOT NULL,
	-- Device that caused the change, so a client can skip echoes of its own writes. Null for server-side actions.
	"actor_device_id" BIGINT,
	-- Event time. Informational - ordering comes from the id, not the clock.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "sync_events" IS 'Append-only change log per account. Devices poll it by id rather than by timestamp, which sidesteps clock skew and makes an event impossible to miss between two polls.';
COMMENT ON COLUMN "sync_events"."id" IS 'Monotonic sequence. Ordering is the point: it is the cursor every device reads against.';
COMMENT ON COLUMN "sync_events"."user_id" IS 'Account whose stream this event belongs to. Shared content is fanned out into each participant stream.';
COMMENT ON COLUMN "sync_events"."file_id" IS 'Affected file. Null for folder-only events.';
COMMENT ON COLUMN "sync_events"."folder_id" IS 'Affected folder. Null for file-only events.';
COMMENT ON COLUMN "sync_events"."action" IS 'created | updated | moved | deleted | restored | permission_changed.';
COMMENT ON COLUMN "sync_events"."actor_device_id" IS 'Device that caused the change, so a client can skip echoes of its own writes. Null for server-side actions.';
COMMENT ON COLUMN "sync_events"."created_at" IS 'Event time. Informational - ordering comes from the id, not the clock.';

CREATE INDEX "idx_sync_events_user_id"
ON "sync_events" ("user_id", "id");

CREATE TABLE IF NOT EXISTS "trash_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Account whose trash this is.
	"owner_id" BIGINT NOT NULL,
	-- Trashed file. Exactly one of file_id and folder_id is set.
	"file_id" BIGINT,
	-- Trashed folder, with its whole subtree.
	"folder_id" BIGINT,
	-- Where it came from, so restore can put it back. Null when that parent has itself been purged.
	"original_folder_id" BIGINT,
	-- Name at deletion time, so a restore into a folder that now has a name clash can rename predictably.
	"original_name" VARCHAR(255) NOT NULL,
	-- Who deleted it - relevant on shared folders where anyone with edit rights can.
	"deleted_by_id" BIGINT,
	-- Retention deadline. The reaper only touches rows past this instant, which is what makes "deleted" reversible for 30 days.
	"purge_after" TIMESTAMPTZ NOT NULL,
	-- When it went to trash.
	"deleted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "trash_items" IS 'The retention record for soft-deleted content. It exists separately from the deleted_at columns because restore needs the original location and the purge job needs a deadline to scan by.';
COMMENT ON COLUMN "trash_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "trash_items"."owner_id" IS 'Account whose trash this is.';
COMMENT ON COLUMN "trash_items"."file_id" IS 'Trashed file. Exactly one of file_id and folder_id is set.';
COMMENT ON COLUMN "trash_items"."folder_id" IS 'Trashed folder, with its whole subtree.';
COMMENT ON COLUMN "trash_items"."original_folder_id" IS 'Where it came from, so restore can put it back. Null when that parent has itself been purged.';
COMMENT ON COLUMN "trash_items"."original_name" IS 'Name at deletion time, so a restore into a folder that now has a name clash can rename predictably.';
COMMENT ON COLUMN "trash_items"."deleted_by_id" IS 'Who deleted it - relevant on shared folders where anyone with edit rights can.';
COMMENT ON COLUMN "trash_items"."purge_after" IS 'Retention deadline. The reaper only touches rows past this instant, which is what makes "deleted" reversible for 30 days.';
COMMENT ON COLUMN "trash_items"."deleted_at" IS 'When it went to trash.';

CREATE INDEX "idx_trash_purge_after"
ON "trash_items" ("purge_after");
CREATE INDEX "idx_trash_owner_deleted"
ON "trash_items" ("owner_id", "deleted_at");

CREATE TABLE IF NOT EXISTS "storage_usage" (
	-- Account this row accounts for. One row per user, so the primary key is the foreign key.
	"user_id" BIGINT,
	-- Sum of file_versions.size_bytes the user owns. This is what counts against quota_bytes - users are billed for what they stored, not for what deduplication saved.
	"logical_bytes" BIGINT NOT NULL DEFAULT 0,
	-- Bytes attributable to this user after dedup, apportioned across sharers of a block. What the storage bill actually costs.
	"physical_bytes" BIGINT NOT NULL DEFAULT 0,
	-- Cached count for the account dashboard.
	"file_count" INTEGER NOT NULL DEFAULT 0,
	-- Portion of logical_bytes held by non-current versions, so a user can see what history is costing them before pruning it.
	"version_bytes" BIGINT NOT NULL DEFAULT 0,
	-- Last full reconciliation. Counters are maintained incrementally and rebuilt from scratch periodically, because incremental counters always drift eventually.
	"recalculated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("user_id")
);

COMMENT ON TABLE "storage_usage" IS 'Materialised quota accounting. Summing versions on every upload would be a table scan on the hot path, so these counters are maintained transactionally and audited by a background job.';
COMMENT ON COLUMN "storage_usage"."user_id" IS 'Account this row accounts for. One row per user, so the primary key is the foreign key.';
COMMENT ON COLUMN "storage_usage"."logical_bytes" IS 'Sum of file_versions.size_bytes the user owns. This is what counts against quota_bytes - users are billed for what they stored, not for what deduplication saved.';
COMMENT ON COLUMN "storage_usage"."physical_bytes" IS 'Bytes attributable to this user after dedup, apportioned across sharers of a block. What the storage bill actually costs.';
COMMENT ON COLUMN "storage_usage"."file_count" IS 'Cached count for the account dashboard.';
COMMENT ON COLUMN "storage_usage"."version_bytes" IS 'Portion of logical_bytes held by non-current versions, so a user can see what history is costing them before pruning it.';
COMMENT ON COLUMN "storage_usage"."recalculated_at" IS 'Last full reconciliation. Counters are maintained incrementally and rebuilt from scratch periodically, because incremental counters always drift eventually.';

ALTER TABLE "users"
ADD FOREIGN KEY("root_folder_id") REFERENCES "folders"("id")
ON UPDATE CASCADE ON DELETE SET NULL;
ALTER TABLE "folders"
ADD FOREIGN KEY("owner_id") REFERENCES "users"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
ALTER TABLE "folders"
ADD FOREIGN KEY("parent_id") REFERENCES "folders"("id")
ON UPDATE CASCADE ON DELETE CASCADE;
